// Deterministic pixel oracles, not screenshots generated by the same implementation.
// Run under a real OpenGL 4.1 context, e.g. xvfb-run with Mesa llvmpipe.
#include <Zamin/Zamin.h>
#include <Zamin/Scene/Terrain.h>
#include <Zamin/Scene/TerrainLOD.h>
#include <Zamin/Renderer/TerrainSurface.h>
#include <Zamin/Utils/FileSystem.h>
#include <glm/gtc/matrix_transform.hpp>
#include <cmath>
#include <cstdio>
#include <stdexcept>
using namespace Zamin;
namespace {
    void Check(bool value, const char* what)
    {
        if (!value) throw std::runtime_error(what);
    }
    void Near(float a, float b, const char* what)
    {
        if (std::abs(a - b) > .012f)
        {
            std::printf("%s: actual %.5f expected %.5f\n", what, a, b);
            throw std::runtime_error(what);
        }
    }
    class TestApp : public Application
    {
    public:
        using Application::Application;
    };
    Ref<Texture2D> Solid(glm::vec4 color)
    {
        TextureSpecification spec;
        spec.Width = spec.Height = 1;
        spec.Format = ImageFormat::RGBA32F;
        spec.SRGB = false;
        spec.GenerateMips = false;
        auto texture = Texture2D::Create(spec);
        texture->SetData(&color, sizeof(color));
        return texture;
    }
    struct Probe
    {
        TerrainComponent Terrain;
        Ref<Framebuffer> Target;
        Ref<Mesh> MeshRef;
        Ref<TerrainSurface> Surface;
        std::vector<Ref<Mesh>> Patches;
        Probe()
        {
            Terrain.Reset(5, { 4, 4 });
            for (auto& l : Terrain.Layers) l.Color = glm::vec3(1);
            Surface = TerrainTools::GetSurface(Terrain);
            MeshRef = TerrainTools::GetRenderMesh(Terrain);
            FramebufferSpecification spec;
            spec.Width = spec.Height = 128;
            spec.Attachments = { FramebufferTextureFormat::RGBA16F, FramebufferTextureFormat::RED_INTEGER, FramebufferTextureFormat::Depth };
            Target = Framebuffer::Create(spec);
        }
        glm::vec4 Draw(RenderDebugView debug = RenderDebugView::Albedo, WireframeMode wire = WireframeMode::Off, bool ordinary = false, bool sun = false)
        {
            Target->Bind();
            RenderCommand::SetClearColor({ 0, 0, 0, 1 });
            RenderCommand::Clear();
            Target->ClearAttachment(1, -1);
            SceneEnvironment env;
            env.DrawSky = false;
            env.HasSun = sun;
            env.Shadows.AtlasSize = 1024;
            env.DebugView = debug;
            env.Wireframe = wire;
            env.AmbientIntensity = 1;
            env.SkyTopColor = env.SkyHorizonColor = env.GroundColor = glm::vec3(1);
            glm::vec3 center(Terrain.Size.x * .5f, 0, Terrain.Size.y * .5f), eye = center + glm::vec3(0, 5, 0);
            Renderer3D::BeginScene(glm::lookAt(eye, center, glm::vec3(0, 0, -1)), glm::ortho(-center.x, center.x, -center.z, center.z, .1f, 10.f), eye, env);
            Material native;
            native.Albedo = { 0, 1, 0, 1 };
            if (ordinary) Renderer3D::SubmitMesh(MeshRef, glm::translate(glm::mat4(1), glm::vec3(0, .1f, 0)) * glm::scale(glm::mat4(1), glm::vec3(.25f)), native, 17);
            if (Patches.empty()) Renderer3D::SubmitTerrain(MeshRef, glm::mat4(1), Surface, 42);
            else
                for (auto& patch : Patches) Renderer3D::SubmitTerrain(patch, glm::mat4(1), Surface, 42);
            native.Albedo = { 1, 1, 0, 1 };
            if (ordinary) Renderer3D::SubmitMesh(MeshRef, glm::translate(glm::mat4(1), glm::vec3(3, .1f, 3)) * glm::scale(glm::mat4(1), glm::vec3(.25f)), native, 19);
            Renderer3D::EndScene();
            glm::vec4 value;
            Check(Target->ReadPixelFloat(0, 64, 64, &value.x), "float pixel");
            int picked = Target->ReadPixel(1, 64, 64);
            if (picked != 42) std::printf("debug=%d wire=%d ordinary=%d picked=%d pixel=%f,%f,%f mesh=%d\n", int(debug), int(wire), int(ordinary), picked, value.x, value.y, value.z, bool(MeshRef));
            Check(picked == 42, "terrain picking including wire fill");
            if (ordinary)
            {
                glm::vec4 before, after;
                Target->ReadPixelFloat(0, 16, 112, &before.x);
                Target->ReadPixelFloat(0, 112, 16, &after.x);
                Near(before.y, 1, "native draw before terrain");
                Near(before.x, 0, "native green tint");
                Near(after.x, 1, "native draw after terrain");
                Near(after.z, 0, "native yellow tint");
                Check(Target->ReadPixel(1, 16, 112) == 17 && Target->ReadPixel(1, 112, 16) == 19, "native draws visible and picked");
            }
            Target->Unbind();
            return value;
        }
    };
}
int main(int argc, char** argv)
{
    ApplicationSpecification spec;
    spec.Name = "Terrain GPU tests";
    spec.EnableImGui = false;
    spec.Window.Width = 320;
    spec.Window.Height = 240;
    spec.Window.VSync = false;
    spec.CommandLineArgs = { argc, argv };
    TestApp app(spec);
    try
    {
        Probe p;
        // RGBA weights are interpolated in linear space. Per-layer maps and scalar parameters.
        std::fill(p.Terrain.Weights.begin(), p.Terrain.Weights.end(), glm::vec4(.1f, .2f, .3f, .4f));
        p.Surface = TerrainTools::GetSurface(p.Terrain);
        glm::vec3 expected(0);
        float rough = 0, metal = 0;
        for (size_t i = 0; i < 4; ++i)
        {
            float f = float(i + 1) / 4;
            glm::vec3 color(f, 1 - f, .25f);
            p.Surface->Albedo[i] = Solid(glm::vec4(color, 1));
            p.Surface->Mask[i] = Solid({ .5f, .5f, .5f, 1 });
            p.Surface->Layers[i].Roughness = f;
            p.Surface->Layers[i].Metallic = 1 - f;
            expected += float(i + 1) * .1f * color;
            rough += float(i + 1) * .1f * f * .5f;
            metal += float(i + 1) * .1f * (1 - f) * .5f;
        }
        auto pixel = p.Draw();
        for (int c = 0; c < 3; ++c) Near(pixel[c], expected[c], "four linear albedo layers");
        Near(p.Draw(RenderDebugView::Roughness).x, std::pow(rough, 2.2f), "ORM roughness blend");
        Near(p.Draw(RenderDebugView::Metallic).x, std::pow(metal, 2.2f), "ORM metallic blend");
        auto flat = p.Draw(RenderDebugView::Normals);
        Near(flat.y, 1, "flat normal fallback");
        Near(flat.x, std::pow(.5f, 2.2f), "flat normal x");
        for (auto& normal : p.Surface->Normal) normal = Solid({ 1, .5f, 1, 1 });
        auto mapped = p.Draw(RenderDebugView::Normals);
        Check(std::abs(mapped.x - flat.x) > .05f || std::abs(mapped.z - flat.z) > .05f, "normal mapping changes world normals");
        for (auto& l : p.Surface->Layers) l.NormalStrength = 0;
        auto disabled = p.Draw(RenderDebugView::Normals);
        Near(disabled.y, 1, "zero normal strength");
        p.Draw(RenderDebugView::Albedo, WireframeMode::Wire);
        p.Draw(RenderDebugView::Albedo, WireframeMode::ShadedWire);
        auto interleaved = p.Draw(RenderDebugView::Albedo, WireframeMode::Off, true);
        Near(interleaved.x, pixel.x, "terrain/native texture bindings");
        // AO affects environment lighting only. All scalar inputs remain live.
        for (auto& l : p.Surface->Layers) l.Occlusion = 1;
        auto lit = p.Draw(RenderDebugView::Lit);
        for (auto& l : p.Surface->Layers) l.Occlusion = 0;
        auto dark = p.Draw(RenderDebugView::Lit);
        Check(lit.x > .01f && dark.x < .001f, "AO applied to environment lighting");
        // Upload/cache contract: no control re-upload for sculpt/material changes; paint once.
        auto uploads = p.Surface->WeightUploads;
        auto control = p.Surface->Weights;
        p.Terrain.Heights[0] = 1;
        p.Terrain.GeometryChanged();
        p.Terrain.Layers[0].Roughness = .7f;
        auto cached = TerrainTools::GetSurface(p.Terrain);
        Check(cached->WeightUploads == uploads && cached->Weights == control, "sculpt/parameter upload cache");
        p.Terrain.Weights[0] = { 0, 1, 0, 0 };
        p.Terrain.PaintChanged();
        TerrainTools::GetSurface(p.Terrain);
        Check(cached->WeightUploads == uploads + 1, "paint uploads control exactly once");
        TerrainTools::GetSurface(p.Terrain);
        Check(cached->WeightUploads == uploads + 1, "unchanged control cached");
        p.Terrain.Reset(17, { 16, 16 });
        TerrainTools::GetSurface(p.Terrain);
        Check(cached->Weights->GetWidth() == 17 && cached->ControlBytes == 17 * 17 * 16, "resized RGBA32F control");
        p.Terrain.Layers[0].TexturePath = "../outside.png";
        p.Terrain.Layers[1].NormalMapPath = "missing-normal.png";
        TerrainTools::GetSurface(p.Terrain);
        Check(cached->MissingMaps == 2 && !cached->Albedo[0] && !cached->Normal[1], "invalid maps use safe fallback");
        TerrainComponent steady;
        steady.Reset(3, { 2, 2 });
        steady.Weights[0] = { 0.419553995f, 0.473033875f, 0.107019663f, 0.000392500137f };
        steady.EnsureSize();
        auto steadySurface = TerrainTools::GetSurface(steady);
        auto steadyUploads = steadySurface->WeightUploads;
        for (int frame = 0; frame < 120; ++frame)
        {
            steady.EnsureSize();
            TerrainTools::GetSurface(steady);
        }
        Check(steadySurface->WeightUploads == steadyUploads, "float-normalized paint does not re-upload every frame");
        // UV detail comes from the source texture on the GPU; changing metre tiling does not bake an albedo.
        p.Terrain.Reset(5, { 4, 4 });
        for (auto& l : p.Terrain.Layers) l.Color = glm::vec3(1);
        p.Surface = TerrainTools::GetSurface(p.Terrain);
        p.MeshRef = TerrainTools::GetRenderMesh(p.Terrain);
        TextureSpecification stripes;
        stripes.Width = 2;
        stripes.Height = 1;
        stripes.Format = ImageFormat::RGBA32F;
        stripes.SRGB = false;
        stripes.GenerateMips = false;
        stripes.Filter = TextureFilter::Nearest;
        auto texture = Texture2D::Create(stripes);
        glm::vec4 colors[] = { { 1, 0, 0, 1 }, { 0, 0, 1, 1 } };
        texture->SetData(colors, sizeof(colors));
        p.Surface->Albedo[0] = texture;
        p.Surface->Layers[0].Tiling = .25f;
        auto blue = p.Draw();
        Near(blue.z, 1, "per-metre UV blue texel");
        p.Surface->Layers[0].Tiling = .125f;
        auto red = p.Draw();
        Near(red.x, 1, "per-metre UV red texel");
        // Full mesh and far LOD patches must use identical global UV/control coordinates.
        p.Terrain.Reset(65, { 64, 64 });
        p.Surface = TerrainTools::GetSurface(p.Terrain);
        p.MeshRef = TerrainTools::GetRenderMesh(p.Terrain);
        p.Surface->Albedo[0] = texture;
        p.Surface->Layers[0].Tiling = .13f;
        p.Draw();
        std::vector<glm::vec4> samples;
        for (int y : { 16, 63, 64, 112 })
            for (int x : { 16, 63, 64, 112 })
            {
                glm::vec4 value;
                p.Target->ReadPixelFloat(0, x, y, &value.x);
                samples.push_back(value);
            }
        p.Patches = TerrainTools::GetRenderPatches(p.Terrain, glm::mat4(1), { 32, 10000, 32 });
        Check(p.Patches.size() == 4 && TerrainTools::GetRenderStats(p.Terrain).Triangles == 8, "far LOD four patches");
        p.Draw();
        size_t sample = 0;
        for (int y : { 16, 63, 64, 112 })
            for (int x : { 16, 63, 64, 112 })
            {
                glm::vec4 value;
                p.Target->ReadPixelFloat(0, x, y, &value.x);
                for (int c = 0; c < 3; ++c) Near(value[c], samples[sample][c], "LOD patch UV/control seam");
                ++sample;
            }
        p.Patches.clear();
        p.Terrain.Reset(5, { 4, 4 });
        p.Surface = TerrainTools::GetSurface(p.Terrain);
        p.MeshRef = TerrainTools::GetRenderMesh(p.Terrain);
        // Shared source library reload replaces data in place; unsafe symlinks are rejected.
        struct TempAssets
        {
            std::filesystem::path Previous = std::filesystem::current_path(), Root;
            TempAssets()
            {
                Root = std::filesystem::temp_directory_path() / ("zamin-terrain-gpu-" + std::to_string(uint64_t(UUID())));
                std::filesystem::create_directories(Root);
                std::filesystem::current_path(Root);
            }
            ~TempAssets()
            {
                std::filesystem::current_path(Previous);
                std::filesystem::remove_all(Root);
            }
        } files;
        uint8_t rgba[] = { 255, 0, 0, 255 };
        Check(Image::WritePNG("source.png", 1, 1, 4, rgba), "write source");
        p.Terrain.Layers[0].TexturePath = "source.png";
        p.Surface = TerrainTools::GetSurface(p.Terrain);
        auto source = p.Surface->Albedo[0];
        Check(bool(source), "load source through texture library");
        Near(p.Draw().x, 1, "source red pixel");
        rgba[0] = 0;
        rgba[2] = 255;
        Check(Image::WritePNG("source.png", 1, 1, 4, rgba), "rewrite source");
        bool failed = false;
        Check(TextureLibrary::Reload(files.Root / "source.png", &failed) == 1 && !failed, "source texture reload");
        Check(source == p.Surface->Albedo[0], "reload preserves shared reference");
        Near(p.Draw().z, 1, "reloaded blue pixel");
        Check(FileSystem::WriteTextFile("source.png", "corrupt image"), "write corrupt source");
        failed = false;
        Check(TextureLibrary::Reload(files.Root / "source.png", &failed) == 0 && failed, "corrupt reload diagnosed");
        Near(p.Draw().z, 1, "corrupt reload retains last working texture");
        p.Terrain.Layers[0].TexturePath = "../escape.png";
        TerrainTools::GetSurface(p.Terrain);
        Check(!p.Surface->Albedo[0], "outside path rejected");
        p.Terrain.Layers[0].TexturePath = "future.png";
        TerrainTools::GetSurface(p.Terrain);
        Check(!p.Surface->Albedo[0], "missing source fallback");
        Check(Image::WritePNG("future.png", 1, 1, 4, rgba), "create missing source");
        TerrainTools::GetSurface(p.Terrain);
        Check(bool(p.Surface->Albedo[0]), "missing source becomes available");
        std::filesystem::create_symlink(files.Previous / "CMakeLists.txt", files.Root / "escape.png");
        p.Terrain.Layers[0].TexturePath = "escape.png";
        TerrainTools::GetSurface(p.Terrain);
        Check(!p.Surface->Albedo[0], "symlink outside assets rejected");
        Renderer::ResetStats();
        p.Draw(RenderDebugView::Lit, WireframeMode::Off, false, true);
        Check(Renderer::GetStats().ShadowCasterCount > 0, "terrain casts sun shadow");
        // Exercise the failure path as well as successful shader-cache loads.
        auto invalidProgram = Shader::Create("Integration_LinkMismatch",
            "#version 410 core\nout vec3 LinkData; void main(){ LinkData=vec3(1); gl_Position=vec4(0,0,0,1); }",
            "#version 410 core\nin vec2 LinkData; out vec4 Color; void main(){ Color=vec4(LinkData,0,1); }");
        Check(invalidProgram && !invalidProgram->IsValid(), "mismatched shader stages rejected");
        invalidProgram.reset();
        Check(RenderCommand::PopErrors() == 0, "failed program cleanup leaves GL error state clean");
        Check(glm::length(p.Draw(RenderDebugView::Albedo, WireframeMode::Off, false, true)) > 0, "valid terrain still draws after link failure");
        std::printf("PASS: terrain GPU blend, ORM, normals, AO, picking, wire, native bindings, control cache, resize, UV/LOD seams, reload recovery, shadow resize, safe fallback\n");
    }
    catch (const std::exception& e)
    {
        std::fprintf(stderr, "FAIL: %s\n", e.what());
        return 1;
    }
    return 0;
}
